import time
def timing_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        end = time.perf_counter()
        wrapper.last_execution_time = end - start
        return result
    wrapper.last_execution_time = 0
    return wrapper

