class SuffixAutomaton:
    class State:
        __slots__ = ('length', 'link', 'next')
        def __init__(self):
            self.length = 0
            self.link = -1
            self.next = {}

    def __init__(self, s):
        self.states = [self.State()]
        self.last = 0
        for c in s:
            self.extend(c)

    def extend(self, c):
        cur = len(self.states)
        self.states.append(self.State())
        self.states[cur].length = self.states[self.last].length + 1
        p = self.last
        while p != -1 and c not in self.states[p].next:
            self.states[p].next[c] = cur
            p = self.states[p].link
        if p == -1:
            self.states[cur].link = 0
        else:
            q = self.states[p].next[c]
            if self.states[p].length + 1 == self.states[q].length:
                self.states[cur].link = q
            else:
                clone = len(self.states)
                self.states.append(self.State())
                self.states[clone].length = self.states[p].length + 1
                self.states[clone].next = self.states[q].next.copy()
                self.states[clone].link = self.states[q].link
                while p != -1 and self.states[p].next.get(c) == q:
                    self.states[p].next[c] = clone
                    p = self.states[p].link
                self.states[q].link = self.states[cur].link = clone
        self.last = cur

