class PersistentSegmentTree:
    class Node:
        __slots__ = ('left', 'right', 'sum')
        def __init__(self, left=None, right=None, sum=0):
            self.left = left
            self.right = right
            self.sum = sum

    def __init__(self, arr):
        self.roots = []
        self.n = len(arr)
        self.roots.append(self.build(0, self.n - 1, arr))

    def build(self, l, r, arr):
        if l == r:
            return self.Node(sum=arr[l])
        mid = (l + r) // 2
        left = self.build(l, mid, arr)
        right = self.build(mid + 1, r, arr)
        return self.Node(left=left, right=right, sum=left.sum + right.sum)

    def update(self, root, l, r, idx, val):
        if l == r:
            return self.Node(sum=val)
        mid = (l + r) // 2
        if idx <= mid:
            left = self.update(root.left, l, mid, idx, val)
            return self.Node(left=left, right=root.right, sum=left.sum + root.right.sum)
        else:
            right = self.update(root.right, mid + 1, r, idx, val)
            return self.Node(left=root.left, right=right, sum=root.left.sum + right.sum)

    def query(self, node, l, r, ql, qr):
        if not node or ql > r or qr < l:
            return 0
        if ql <= l and r <= qr:
            return node.sum
        mid = (l + r) // 2
        return self.query(node.left, l, mid, ql, qr) + self.query(node.right, mid + 1, r, ql, qr)

