class LinkCutTree:
    class Node:
        __slots__ = ('left', 'right', 'parent', 'rev', 'val', 'sum')
        def __init__(self, val):
            self.left = None
            self.right = None
            self.parent = None
            self.rev = False
            self.val = val
            self.sum = val

    def push(self, x):
        if x and x.rev:
            x.left, x.right = x.right, x.left
            if x.left:
                x.left.rev ^= True
            if x.right:
                x.right.rev ^= True
            x.rev = False

    def update(self, x):
        if x:
            x.sum = x.val
            if x.left:
                x.sum += x.left.sum
            if x.right:
                x.sum += x.right.sum

    def is_root(self, x):
        return not x.parent or (x.parent.left != x and x.parent.right != x)

    def rotate(self, x):
        p = x.parent
        g = p.parent
        if not self.is_root(p):
            if g.left == p:
                g.left = x
            else:
                g.right = x
        x.parent = g
        if p.left == x:
            p.left = x.right
            if x.right:
                x.right.parent = p
            x.right = p
        else:
            p.right = x.left
            if x.left:
                x.left.parent = p
            x.left = p
        p.parent = x
        self.update(p)
        self.update(x)

    def splay(self, x):
        while not self.is_root(x):
            p = x.parent
            if not self.is_root(p):
                g = p.parent
                if (g.left == p) == (p.left == x):
                    self.rotate(p)
                else:
                    self.rotate(x)
            self.rotate(x)

