class Treap:
    import random
    class Node:
        __slots__ = ('key', 'priority', 'left', 'right', 'size')
        def __init__(self, key):
            self.key = key
            self.priority = random.randint(1, 10**9)
            self.left = None
            self.right = None
            self.size = 1

    def __init__(self):
        self.random = __import__('random')

    def update_size(self, node):
        if node:
            node.size = 1
            if node.left:
                node.size += node.left.size
            if node.right:
                node.size += node.right.size

    def split(self, node, key):
        if not node:
            return None, None
        if node.key <= key:
            left, right = self.split(node.right, key)
            node.right = left
            self.update_size(node)
            return node, right
        else:
            left, right = self.split(node.left, key)
            node.left = right
            self.update_size(node)
            return left, node

    def merge(self, left, right):
        if not left or not right:
            return left or right
        if left.priority > right.priority:
            left.right = self.merge(left.right, right)
            self.update_size(left)
            return left
        else:
            right.left = self.merge(left, right.left)
            self.update_size(right)
            return right

    def insert(self, node, key):
        if not node:
            return self.Node(key)
        if self.random.random() < 0.5:
            left, right = self.split(node, key)
            new_node = self.Node(key)
            return self.merge(self.merge(left, new_node), right)
        if key < node.key:
            node.left = self.insert(node.left, key)
        else:
            node.right = self.insert(node.right, key)
        self.update_size(node)
        return node

    def kth_smallest(self, node, k):
        left_size = node.left.size if node.left else 0
        if k == left_size + 1:
            return node.key
        elif k <= left_size:
            return self.kth_smallest(node.left, k)
        else:
            return self.kth_smallest(node.right, k - left_size - 1)

