class CentroidDecomposition:
    def __init__(self, n, edges):
        self.n = n
        self.adj = [[] for _ in range(n)]
        for u, v in edges:
            self.adj[u].append(v)
            self.adj[v].append(u)
        self.size = [0] * n
        self.removed = [False] * n
        self.parent = [-1] * n
        self.build(0)

    def dfs_size(self, u, p):
        self.size[u] = 1
        for v in self.adj[u]:
            if v != p and not self.removed[v]:
                self.dfs_size(v, u)
                self.size[u] += self.size[v]

    def find_centroid(self, u, p, total):
        for v in self.adj[u]:
            if v != p and not self.removed[v] and self.size[v] > total // 2:
                return self.find_centroid(v, u, total)
        return u

    def build(self, u, p=-1):
        self.dfs_size(u, -1)
        centroid = self.find_centroid(u, -1, self.size[u])
        self.parent[centroid] = p
        self.removed[centroid] = True
        for v in self.adj[centroid]:
            if not self.removed[v]:
                self.build(v, centroid)

