            self.b = b
        def eval(self, x):
            return self.m * x + self.b

    def __init__(self):
        self.lines = []
        self.pointer = 0

    def intersect(self, l1, l2):
        return (l2.b - l1.b) / (l1.m - l2.m)

    def add_line(self, m, b):
        new_line = self.Line(m, b)
        while len(self.lines) >= 2:
            l1, l2 = self.lines[-2], self.lines[-1]
            if self.intersect(l1, l2) >= self.intersect(l2, new_line):
                self.lines.pop()
            else:
                break
        self.lines.append(new_line)

    def query(self, x):
        while self.pointer + 1 < len(self.lines) and self.lines[self.pointer].eval(x) < self.lines[self.pointer + 1].eval(x):
            self.pointer += 1
        return self.lines[self.pointer].eval(x)

