class LiChaoTree:
    class Line:
        __slots__ = ('m', 'b')
        def __init__(self, m=0, b=float('inf')):
            self.m = m
            self.b = b
        def eval(self, x):
            return self.m * x + self.b

    def __init__(self, xs):
        self.xs = sorted(set(xs))
        self.n = len(self.xs)
        self.tree = [self.Line() for _ in range(4 * self.n)]

    def add_line(self, node, l, r, new_line):
        mid = (l + r) // 2
        left_x = self.xs[l]
        mid_x = self.xs[mid]
        right_x = self.xs[r]

        if new_line.eval(mid_x) < self.tree[node].eval(mid_x):
            self.tree[node], new_line = new_line, self.tree[node]

        if l == r:
            return

        if new_line.eval(left_x) < self.tree[node].eval(left_x):
            self.add_line(node*2, l, mid, new_line)
        elif new_line.eval(right_x) < self.tree[node].eval(right_x):
            self.add_line(node*2+1, mid+1, r, new_line)

    def query(self, node, l, r, x_idx):
        x = self.xs[x_idx]
        res = self.tree[node].eval(x)
        if l == r:
            return res
        mid = (l + r) // 2
        if x_idx <= mid:
            res = min(res, self.query(node*2, l, mid, x_idx))
        else:
            res = min(res, self.query(node*2+1, mid+1, r, x_idx))
        return res

