def kmp_automaton(pattern, alphabet_size=26):
    m = len(pattern)
    aut = [[0] * alphabet_size for _ in range(m + 1)]
    lps = [0] * m
    length = 0
    i = 1
    while i < m:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    for i in range(m + 1):
        for c in range(alphabet_size):
            char = chr(ord('a') + c)
            if i < m and char == pattern[i]:
                aut[i][c] = i + 1
            elif i > 0:
                aut[i][c] = aut[lps[i - 1]][c]
            else:
                aut[i][c] = 0
    return aut

