class SimHash:
    def __init__(self, dimensions=64):
        self.dimensions = dimensions

    def compute(self, features):
        v = [0] * self.dimensions
        for feature, weight in features.items():
            h = hash(feature)
            for i in range(self.dimensions):
                if (h >> i) & 1:
                    v[i] += weight
                else:
                    v[i] -= weight
        fingerprint = 0
        for i in range(self.dimensions):
            if v[i] > 0:
                fingerprint |= (1 << i)
