class HyperLogLog:
    def __init__(self, b):
        self.b = b
        self.m = 1 << b
        self.registers = [0] * self.m
        self.alpha = self._get_alpha()

    def _get_alpha(self):
        if self.m == 16:
            return 0.673
        elif self.m == 32:
            return 0.697
        elif self.m == 64:
            return 0.709
        return 0.7213 / (1 + 1.079 / self.m)

    def _rho(self, w):
        return (w.bit_length() - w.bit_count() + 1) if w else 64

    def add(self, val):
        x = hash(val)
        j = x & (self.m - 1)
        w = x >> self.b
        self.registers[j] = max(self.registers[j], self._rho(w))

    def count(self):
        Z = sum(2.0 ** -r for r in self.registers)
        E = self.alpha * self.m * self.m / Z
        return int(E)

