class MinHash:
    def __init__(self, num_hashes):
        self.num_hashes = num_hashes
        self.max_hash = (1 << 32) - 1
        self.hash_seeds = [(i * 2654435761) & self.max_hash for i in range(num_hashes)]

    def _hash(self, item, seed):
        return (hash(item) ^ seed) & self.max_hash

    def compute_signature(self, items):
        sig = [self.max_hash] * self.num_hashes
        for item in items:
            for i in range(self.num_hashes):
                h = self._hash(item, self.hash_seeds[i])
                if h < sig[i]:
                    sig[i] = h
        return sig

    def jaccard_estimate(self, sig1, sig2):
        matches = sum(1 for a, b in zip(sig1, sig2) if a == b)
        return matches / self.num_hashes

