def aho_corasick_build(patterns):
    class Node:
        __slots__ = ('next', 'fail', 'output')
        def __init__(self):
            self.next = {}
            self.fail = None
            self.output = []

    root = Node()
    for i, pattern in enumerate(patterns):
        node = root
        for char in pattern:
            if char not in node.next:
                node.next[char] = Node()
            node = node.next[char]
        node.output.append(i)

    queue = []
    for char, node in root.next.items():
        node.fail = root
        queue.append(node)

    while queue:
        current = queue.pop(0)
        for char, child in current.next.items():
            queue.append(child)
            fail = current.fail
            while fail and char not in fail.next:
                fail = fail.fail
            child.fail = fail.next[char] if fail and char in fail.next else root
            child.output.extend(child.fail.output)
    return root

def aho_corasick_search(text, patterns):
    root = aho_corasick_build(patterns)
    results = []
    node = root
    for i, char in enumerate(text):
        while node and char not in node.next:
            node = node.fail
        node = node.next[char] if node and char in node.next else root
        if node:
            for pi in node.output:
                results.append((i - len(patterns[pi]) + 1, patterns[pi]))
    return results

