class UnionFindRollback:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if x == y:
            self.history.append((-1, -1, -1))
            return False
        if self.size[x] < self.size[y]:
            x, y = y, x
        self.history.append((x, y, self.size[x]))
        self.parent[y] = x
        self.size[x] += self.size[y]
        return True

    def rollback(self):
        if not self.history:
            return
        x, y, sz = self.history.pop()
        if x != -1:
            self.parent[y] = y
            self.size[x] = sz

    def snapshot(self):
        return len(self.history)

    def rollback_to(self, snap):
        while len(self.history) > snap:
            self.rollback()

