class AVLTreeOptimized:
    class Node:
        __slots__ = ('key', 'left', 'right', 'height', 'count')
        def __init__(self, key):
            self.key = key
            self.left = None
            self.right = None
            self.height = 1
            self.count = 1

    def __init__(self):
        self.root = None

    def height(self, node):
        return node.height if node else 0

    def balance(self, node):
        return self.height(node.left) - self.height(node.right) if node else 0

    def update(self, node):
        if node:
            node.height = 1 + max(self.height(node.left), self.height(node.right))
            node.count = 1
            if node.left:
                node.count += node.left.count
            if node.right:
                node.count += node.right.count

    def rotate_right(self, y):
        x = y.left
        T = x.right
        x.right = y
        y.left = T
        self.update(y)
        self.update(x)
        return x

    def rotate_left(self, x):
        y = x.right
        T = y.left
        y.left = x
        x.right = T
        self.update(x)
        self.update(y)
        return y

    def insert(self, node, key):
        if not node:
            return self.Node(key)
        if key < node.key:
            node.left = self.insert(node.left, key)
        elif key > node.key:
            node.right = self.insert(node.right, key)
        else:
            node.count += 1
            return node
        self.update(node)
        bal = self.balance(node)
        if bal > 1 and key < node.left.key:
            return self.rotate_right(node)
        if bal < -1 and key > node.right.key:
            return self.rotate_left(node)
        if bal > 1 and key > node.left.key:
            node.left = self.rotate_left(node.left)
            return self.rotate_right(node)
        if bal < -1 and key < node.right.key:
            node.right = self.rotate_right(node.right)
            return self.rotate_left(node)
        return node

    def kth_smallest(self, node, k):
        left_count = node.left.count if node.left else 0
        if k <= left_count:
            return self.kth_smallest(node.left, k)
        elif k <= left_count + node.count - (node.right.count if node.right else 0):
            return node.key
        else:
            return self.kth_smallest(node.right, k - left_count - (node.count - (node.right.count if node.right else 0)))

