class WaveletTree:
    def __init__(self, arr):
        self.min_val = min(arr)
        self.max_val = max(arr)
        self.build(arr, 0)

    def build(self, arr, level):
        self.level = level
        if self.min_val == self.max_val or len(arr) <= 1:
            self.is_leaf = True
            self.arr = arr
            return
        self.is_leaf = False
        mid = (self.min_val + self.max_val) // 2
        left = []
        right = []
        self.b = [0] * len(arr)
        for i, x in enumerate(arr):
            if x <= mid:
                left.append(x)
                self.b[i] = 1
            else:
                right.append(x)
        self.prefix_sum = [0]
        for bit in self.b:
            self.prefix_sum.append(self.prefix_sum[-1] + bit)
        self.left_child = WaveletTree(left) if left else None
        self.right_child = WaveletTree(right) if right else None

    def rank(self, val, idx):
        if self.is_leaf or idx <= 0:
            return idx if self.min_val == val else 0
        mid = (self.min_val + self.max_val) // 2
        if val <= mid:
            return self.left_child.rank(val, self.prefix_sum[idx]) if self.left_child else 0
        else:
            return self.right_child.rank(val, idx - self.prefix_sum[idx]) if self.right_child else 0

    def quantile(self, k, left, right):
        if self.is_leaf:
            return self.min_val
        left_ones_in_range = self.prefix_sum[right] - self.prefix_sum[left]
        if k <= left_ones_in_range:
            return self.left_child.quantile(k, self.prefix_sum[left], self.prefix_sum[right]) if self.left_child else self.min_val
        else:
            return self.right_child.quantile(k - left_ones_in_range, left - self.prefix_sum[left], right - self.prefix_sum[right]) if self.right_child else self.max_val

