class FMIndex:
    def __init__(self, text):
        self.text = text + '$'
        self.sa = self.build_sa()
        self.bwt = self.build_bwt()
        self.c = self.build_c_table()
        self.occ = self.build_occ_table()

    def build_sa(self):
        n = len(self.text)
        sa = list(range(n))
        rank = [ord(c) for c in self.text]
        tmp = [0] * n
        k = 1
        while True:
            sa.sort(key=lambda x: (rank[x], rank[x+k] if x+k < n else -1))
            tmp[sa[0]] = 0
            for i in range(1, n):
                prev, cur = sa[i-1], sa[i]
                tmp[cur] = tmp[prev]
                if (rank[prev], rank[prev+k] if prev+k < n else -1) != (rank[cur], rank[cur+k] if cur+k < n else -1):
                    tmp[cur] += 1
            rank, tmp = tmp, rank
            if rank[sa[-1]] == n - 1:
                break
            k <<= 1
        return sa

    def build_bwt(self):
        return [self.text[i-1] if i > 0 else self.text[-1] for i in self.sa]

    def build_c_table(self):
        c = {}
        sorted_chars = sorted(set(self.text))
        count = 0
        for char in sorted_chars:
            c[char] = count
            count += self.text.count(char) - 1 if char == '$' else self.text[:-1].count(char)
        return c

    def build_occ_table(self):
        occ = {char: [0] for char in set(self.text)}
        for char in self.bwt:
            for c in occ:
                occ[c].append(occ[c][-1] + (1 if char == c else 0))
        return occ

    def count_occurrences(self, pattern):
        l, r = 0, len(self.text) - 1
        for char in reversed(pattern):
            if char not in self.c:
                return 0
            l = self.c[char] + (self.occ[char][l] if l > 0 else 0)
            r = self.c[char] + self.occ[char][r+1] - 1
            if l > r:
                return 0
        return r - l + 1

