class RabinKarpRolling:
    def __init__(self, base=256, mod=10**9+7):
        self.base = base
        self.mod = mod

    def compute_hashes(self, s, window_len):
        n = len(s)
        if n < window_len:
            return []
        powers = [1]
        for i in range(1, window_len):
            powers.append((powers[-1] * self.base) % self.mod)

        hash_val = 0
        for i in range(window_len):
            hash_val = (hash_val * self.base + ord(s[i])) % self.mod

        result = [hash_val]
        for i in range(window_len, n):
            hash_val = (hash_val - ord(s[i-window_len]) * powers[window_len-1]) % self.mod
            hash_val = (hash_val * self.base + ord(s[i])) % self.mod
            result.append(hash_val)
        return result

