class TolerantBloomFilter:
    def __init__(self, size, num_hashes):
        self.size = size
        self.num_hashes = num_hashes
        self.ones = [0] * size
        self.count = [0] * size

    def _get_hashes(self, item):
        return [(hash(str(i) + str(item)) % self.size) for i in range(self.num_hashes)]

    def add(self, item):
        indices = self._get_hashes(item)
        for idx in indices:
            self.ones[idx] = 1
            self.count[idx] += 1

    def remove(self, item):
        indices = self._get_hashes(item)
        if self.contains(item):
            for idx in indices:
                self.count[idx] = max(0, self.count[idx] - 1)
                if self.count[idx] == 0:
                    self.ones[idx] = 0

    def contains(self, item):
        indices = self._get_hashes(item)
        return all(self.ones[idx] == 1 for idx in indices)

