class VanEmdeBoas:
    def __init__(self, universe_size):
        self.u = 1
        while self.u < universe_size:
            self.u <<= 1
        self.min = None
        self.max = None
        if self.u > 2:
            self.sqrt_u = 1 << ((self.u.bit_length() + 1) // 2)
            self.summary = None
            self.cluster = [None] * (self.u // self.sqrt_u)

    def high(self, x):
        return x // self.sqrt_u

    def low(self, x):
        return x % self.sqrt_u

    def index(self, h, l):
        return h * self.sqrt_u + l

    def insert(self, x):
        if self.min is None:
            self.min = self.max = x
            return
        if x < self.min:
            x, self.min = self.min, x
        if self.u > 2:
            h = self.high(x)
            if self.cluster[h] is None:
                self.cluster[h] = VanEmdeBoas(self.sqrt_u)
            if self.summary is None:
                self.summary = VanEmdeBoas(self.sqrt_u)
            if self.cluster[h].min is None:
                self.summary.insert(h)
            self.cluster[h].insert(self.low(x))
        if x > self.max:
            self.max = x

    def successor(self, x):
        if self.min is None:
            return None
        if x < self.min:
            return self.min
        if self.u == 2:
            if x == 0 and self.max == 1:
                return 1
            return None
        h = self.high(x)
        if self.cluster[h] is not None and x < self.index(h, self.cluster[h].max):
            offset = self.cluster[h].successor(self.low(x))
            return self.index(h, offset)
        if self.summary is None:
            return None
        succ_cluster = self.summary.successor(h)
        if succ_cluster is None:
            return None
        offset = self.cluster[succ_cluster].min
        return self.index(succ_cluster, offset)

