class MerkleTree:
    import hashlib
    def __init__(self, data_blocks):
        self.leaves = [self.hash_block(b) for b in data_blocks]
        self.tree = [self.leaves]
        self.build()

    def hash_block(self, data):
        import hashlib
        return hashlib.sha256(str(data).encode()).hexdigest()

    def hash_pair(self, a, b):
        import hashlib
        return hashlib.sha256((a+b).encode()).hexdigest()

    def build(self):
        current_level = self.leaves
        while len(current_level) > 1:
            next_level = []
            for i in range(0, len(current_level), 2):
                if i + 1 < len(current_level):
                    next_level.append(self.hash_pair(current_level[i], current_level[i+1]))
                else:
                    next_level.append(self.hash_pair(current_level[i], current_level[i]))
            self.tree.append(next_level)
            current_level = next_level

    def root(self):
        return self.tree[-1][0] if self.tree else None

