class BinomialHeap:
    class Node:
        __slots__ = ('key', 'degree', 'child', 'sibling')
        def __init__(self, key):
            self.key = key
            self.degree = 0
            self.child = None
            self.sibling = None

    def __init__(self):
        self.head = None

    def merge(self, h1, h2):
        if not h1:
            return h2
        if not h2:
            return h1
        if h1.degree <= h2.degree:
            h1.sibling = self.merge(h1.sibling, h2)
            return h1
        else:
            h2.sibling = self.merge(h1, h2.sibling)
            return h2

    def union(self, h1, h2):
        h = self.merge(h1, h2)
        if not h:
            return None
        prev = None
        curr = h
        next = curr.sibling
        while next:
            if curr.degree != next.degree or (next.sibling and next.sibling.degree == curr.degree):
                prev = curr
                curr = next
            else:
                if curr.key <= next.key:
                    curr.sibling = next.sibling
                    next.sibling = curr.child
                    curr.child = next
                    curr.degree += 1
                else:
                    if not prev:
                        h = next
                    else:
                        prev.sibling = next
                    curr.sibling = next.child
                    next.child = curr
                    next.degree += 1
                    curr = next
            next = curr.sibling
        return h

    def insert(self, key):
        node = self.Node(key)
        self.head = self.union(self.head, node)

    def find_min(self):
        if not self.head:
            return None
        min_node = self.head
        curr = self.head.sibling
        while curr:
            if curr.key < min_node.key:
                min_node = curr
            curr = curr.sibling
        return min_node.key

